// One Apify search per location. Separate locations with new lines or ";".
const form = $input.first().json;
const term = String(form['Search term'] || 'HVAC contractor').trim();
const max = Math.min(Math.max(parseInt(form['Max results per location'], 10) || 50, 1), 500);
const locations = String(form['Locations'] || '')
  .split(/[\n;]+/)
  .map((s) => s.trim())
  .filter(Boolean);

return [...new Set(locations)].map((location) => ({
  json: {
    location,
    apifyInput: {
      searchStringsArray: [term],
      locationQuery: location,
      maxCrawledPlacesPerSearch: max,
      language: 'en',
      skipClosedPlaces: true,
    },
  },
}));

// Apify returns one item per business. Remove duplicates/closed places and score.
const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const p = item.json;
  const id = p.placeId || p.url || p.title;
  if (!p.title || !id || seen.has(id)) continue;
  if (p.permanentlyClosed || p.temporarilyClosed) continue;
  seen.add(id);

  const phone = p.phone || p.phoneUnformatted || '';
  const reviews = Number(p.reviewsCount) || 0;
  const rating = Number(p.totalScore) || 0;
  const reasons = [];
  let score = 0;

  if (phone) { score += 30; reasons.push('has phone'); }
  if (reviews >= 5 && reviews <= 150) { score += 30; reasons.push('small/medium shop'); }
  else if (reviews > 150 && reviews <= 400) { score += 10; reasons.push('mid-size shop'); }
  else if (reviews > 400) { reasons.push('large company (likely has call center)'); }
  else { reasons.push('very few reviews'); }
  if (p.website) { score += 20; reasons.push('has website'); }
  if (rating && rating < 4.3) { score += 10; reasons.push('rating could improve'); }

  out.push({
    json: {
      place_id: id,
      business_name: p.title,
      phone,
      international_phone: p.phoneUnformatted || '',
      website: p.website || '',
      address: p.address || '',
      search_location: p.searchString ? [p.city, p.state, p.countryCode].filter(Boolean).join(', ') : '',
      category: p.categoryName || '',
      rating,
      reviews,
      google_maps_url: p.url || '',
      lead_score: score,
      score_reasons: reasons.join(', '),
    },
  });
}

return out;

// Reads each website's HTML: finds emails and checks whether the business
// already has online booking or a chat widget (if not, they need you more).
const leads = $('Clean + Score').all();
const pages = $input.all();

const BOOKING = /servicetitan|housecallpro|housecall pro|jobber|scheduleengine|book online|schedule online|book now/i;
const CHAT = /podium|birdeye|tawk\.to|livechat|intercom|drift\.com|hs-scripts|smith\.ai|ruby\.com/i;
const JUNK = /\.(png|jpe?g|gif|svg|webp)$|example\.|sentry|wixpress|domain\.com|yourname|email\.com/i;

return leads.map((lead, i) => {
  const page = pages[i] ? pages[i].json : {};
  const html = typeof page.data === 'string' ? page.data : '';
  const l = { ...lead.json };

  const emails = [...new Set(
    (html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
      .map((e) => e.toLowerCase())
      .filter((e) => !JUNK.test(e))
  )];

  l.email = emails[0] || '';
  l.all_emails = emails.slice(0, 5).join(', ');
  l.website_checked = html.length > 0;
  l.has_online_booking = html ? BOOKING.test(html) : '';
  l.has_chat_widget = html ? CHAT.test(html) : '';

  const reasons = l.score_reasons ? [l.score_reasons] : [];
  if (l.email) { l.lead_score += 10; reasons.push('email found'); }
  if (html && !l.has_online_booking && !l.has_chat_widget) {
    l.lead_score += 10;
    reasons.push('no online booking or chat');
  }
  l.score_reasons = reasons.join(', ');
  l.lead_status = l.lead_score >= 70 ? 'HOT' : l.lead_score >= 40 ? 'WARM' : 'COLD';
  l.scraped_at = new Date().toISOString();
  return { json: l };
});
